CREATE OR REPLACE FUNCTION public.challenge_streaks(_c uuid,_u uuid,_today date DEFAULT CURRENT_DATE) RETURNS TABLE(checkins integer,current_streak integer,best_streak integer,last_date date) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$
 WITH ch AS(SELECT starts_on,frequency FROM challenges WHERE id=_c), d AS(SELECT ci.checkin_date,CASE WHEN ch.frequency='weekly' THEN (ci.checkin_date-ch.starts_on)/7 ELSE ci.checkin_date-ch.starts_on END period FROM challenge_checkins ci CROSS JOIN ch WHERE ci.challenge_id=_c AND ci.user_id=_u), unique_period AS(SELECT period,max(checkin_date) last FROM d GROUP BY period), grouped AS(SELECT period,last,period-(row_number() OVER(ORDER BY period))::int grp FROM unique_period), runs AS(SELECT grp,count(*)::int len,max(period) period,max(last) last FROM grouped GROUP BY grp), current_period AS(SELECT CASE WHEN frequency='weekly' THEN (_today-starts_on)/7 ELSE _today-starts_on END period FROM ch)
 SELECT (SELECT count(*)::int FROM unique_period),coalesce((SELECT len FROM runs WHERE period=(SELECT max(period) FROM runs) AND period>=(SELECT period-1 FROM current_period)),0),coalesce((SELECT max(len) FROM runs),0),(SELECT max(last) FROM runs); $$;
REVOKE ALL ON FUNCTION public.challenge_streaks(uuid,uuid,date) FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.my_challenge_progress(_c uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE c challenges; s record; BEGIN SELECT * INTO c FROM challenges WHERE id=_c; IF NOT FOUND OR NOT public.challenge_member_active(_c,auth.uid()) THEN RAISE EXCEPTION 'not_joined'; END IF; SELECT * INTO s FROM public.challenge_streaks(_c,auth.uid(),(now() AT TIME ZONE coalesce(c.timezone,'UTC'))::date); RETURN jsonb_build_object('total',s.checkins,'current',s.current_streak,'best',s.best_streak); END; $$;
REVOKE ALL ON FUNCTION public.my_challenge_progress(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.my_challenge_progress(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.guard_challenge_message_schedule() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c challenges; BEGIN SELECT * INTO c FROM challenges WHERE id=NEW.challenge_id; IF NEW.enabled AND (NEW.kind<>'welcome' OR length(trim(NEW.body_en||NEW.body_es))=0) OR NEW.send_hour NOT BETWEEN 0 AND 23 OR NEW.send_offset_days NOT BETWEEN -7 AND c.ends_on-c.starts_on+1 THEN RAISE EXCEPTION 'invalid_messages'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER challenge_message_schedule_guard BEFORE INSERT OR UPDATE ON public.challenge_messages FOR EACH ROW EXECUTE FUNCTION public.guard_challenge_message_schedule();
REVOKE ALL ON FUNCTION public.guard_challenge_message_schedule() FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.challenge_host_enrollments(_c uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.can_manage_challenge(_c) THEN RAISE EXCEPTION 'not_allowed'; END IF; RETURN coalesce((SELECT jsonb_agg(jsonb_build_object('user_id',m.user_id,'name',p.full_name,'status',m.access_status,'extras',m.extras,'joined_at',m.joined_at)) FROM challenge_members m LEFT JOIN profiles p ON p.id=m.user_id WHERE m.challenge_id=_c),'[]'); END; $$;
REVOKE ALL ON FUNCTION public.challenge_host_enrollments(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.challenge_host_enrollments(uuid) TO authenticated;
CREATE FUNCTION public.my_challenge_list() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce(jsonb_agg(jsonb_build_object('id',c.id,'title_en',c.title_en,'title_es',c.title_es,'starts_on',c.starts_on,'ends_on',c.ends_on,'timezone',c.timezone)),'[]') FROM challenges c WHERE auth.uid() IS NOT NULL AND public.challenge_member_active(c.id,auth.uid()); $$;
REVOKE ALL ON FUNCTION public.my_challenge_list() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.my_challenge_list() TO authenticated;
REVOKE EXECUTE ON FUNCTION public.my_challenges() FROM authenticated; COMMENT ON FUNCTION public.my_challenges() IS 'DEPRECATED: use caller-scoped minimal my_challenge_list';